// C implementation of vstodo cmdMerge header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_merge.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_merge.go.\n\n#ifndef VSTODO_C_CMD_MERGE_H\n#define VSTODO_C_CMD_MERGE_H\n\n// Merge a branch into the current branch.\n// Equivalent to Go cmdMerge function.\n// app — vstodo application context pointer\n// args — branch name to merge\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_merge(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_MERGE_H